"use client";

import { useEffect, useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Group,
  ShaderMaterial,
  Vector3,
} from "three";
import { linkVertex, linkFragment, nodeVertex, nodeFragment } from "@/shaders/links";
import { TECHNOLOGIES, TECH_LINKS } from "@/data/technologies";
import { journey } from "@/lib/journey";
import { useAppStore } from "@/store/useAppStore";
import { C } from "@/lib/palette";
import { clamp, damp, smootherstep } from "@/lib/math";

const SCALE = 1.16;
const SEGMENTS = 18;

export const NODE_POSITIONS = TECHNOLOGIES.map(
  (t) =>
    [t.position[0] * SCALE, t.position[1] * SCALE, t.position[2] * SCALE] as [
      number,
      number,
      number,
    ],
);

/**
 * The technology constellation: nodes wired into a structure the particle
 * field is simultaneously drawing. Hovering a technology in the DOM focuses
 * the matching node and lights every link that touches it.
 */
export function Constellation() {
  const group = useRef<Group>(null);

  const linkGeometry = useMemo(() => {
    const perLink = SEGMENTS * 2;
    const total = TECH_LINKS.length * perLink;

    const positions = new Float32Array(total * 3);
    const ts = new Float32Array(total);
    const ids = new Float32Array(total);
    const ends = new Float32Array(total * 2);

    const a = new Vector3();
    const b = new Vector3();
    const mid = new Vector3();
    const p = new Vector3();

    let v = 0;
    TECH_LINKS.forEach((link, li) => {
      a.fromArray(NODE_POSITIONS[link[0]]);
      b.fromArray(NODE_POSITIONS[link[1]]);

      // Bow each wire outward from the centre so the structure reads as a
      // volume rather than a flat web of straight lines.
      mid.addVectors(a, b).multiplyScalar(0.5);
      const bow = mid.clone().normalize().multiplyScalar(0.34 + (li % 3) * 0.07);
      mid.add(bow);

      const sample = (t: number, out: Vector3) => {
        const it = 1 - t;
        out.set(0, 0, 0);
        out.addScaledVector(a, it * it);
        out.addScaledVector(mid, 2 * it * t);
        out.addScaledVector(b, t * t);
        return out;
      };

      for (let s = 0; s < SEGMENTS; s++) {
        const t0 = s / SEGMENTS;
        const t1 = (s + 1) / SEGMENTS;

        sample(t0, p);
        positions.set([p.x, p.y, p.z], v * 3);
        ts[v] = t0;
        ids[v] = li;
        ends[v * 2] = link[0];
        ends[v * 2 + 1] = link[1];
        v++;

        sample(t1, p);
        positions.set([p.x, p.y, p.z], v * 3);
        ts[v] = t1;
        ids[v] = li;
        ends[v * 2] = link[0];
        ends[v * 2 + 1] = link[1];
        v++;
      }
    });

    const g = new BufferGeometry();
    g.setAttribute("position", new BufferAttribute(positions, 3));
    g.setAttribute("aT", new BufferAttribute(ts, 1));
    g.setAttribute("aLink", new BufferAttribute(ids, 1));
    g.setAttribute("aEnds", new BufferAttribute(ends, 2));
    return g;
  }, []);

  const linkMaterial = useMemo(
    () =>
      new ShaderMaterial({
        vertexShader: linkVertex,
        fragmentShader: linkFragment,
        transparent: true,
        depthWrite: false,
        blending: AdditiveBlending,
        uniforms: {
          uTime: { value: 0 },
          uOpacity: { value: 0 },
          uReveal: { value: 0 },
          uActiveTech: { value: -1 },
          uColor: { value: C.ion.clone() },
          uPulseColor: { value: C.ionSoft.clone() },
        },
      }),
    [],
  );

  const nodeMaterials = useMemo(
    () =>
      TECHNOLOGIES.map(
        () =>
          new ShaderMaterial({
            vertexShader: nodeVertex,
            fragmentShader: nodeFragment,
            transparent: true,
            depthWrite: false,
            blending: AdditiveBlending,
            uniforms: {
              uTime: { value: 0 },
              uFocus: { value: 0 },
              uOpacity: { value: 0 },
              uColor: { value: C.ion.clone() },
              uFocusColor: { value: C.ionSoft.clone() },
            },
          }),
      ),
    [],
  );

  useEffect(
    () => () => {
      linkGeometry.dispose();
      linkMaterial.dispose();
      nodeMaterials.forEach((m) => m.dispose());
    },
    [linkGeometry, linkMaterial, nodeMaterials],
  );

  const opacity = useRef(0);

  useFrame((state, dt) => {
    const d = Math.min(dt, 1 / 30);
    const t = state.clock.elapsedTime;
    const stage = journey.stage;

    // Present through the technology beat only.
    // Cleared well before the work portal arrives — stray nodes lingering at
    // the edge of frame read as debris, not atmosphere.
    const target = smootherstep(2.35, 3.0, stage) * (1 - smootherstep(3.45, 3.85, stage));
    opacity.current = damp(opacity.current, target, 4.5, d);
    const o = opacity.current;

    const g = group.current;
    if (g) {
      g.visible = o > 0.006;
      if (!g.visible) return;
      g.rotation.y = Math.sin(t * 0.06) * 0.14 + journey.smoothPointer.x * 0.2;
      g.rotation.x = Math.cos(t * 0.05) * 0.08 - journey.smoothPointer.y * 0.12;
    }

    const active = useAppStore.getState().activeTech;

    linkMaterial.uniforms.uTime.value = t;
    linkMaterial.uniforms.uOpacity.value = o;
    linkMaterial.uniforms.uActiveTech.value = active;
    linkMaterial.uniforms.uReveal.value = damp(
      linkMaterial.uniforms.uReveal.value as number,
      clamp((stage - 2.45) / 0.5),
      3,
      d,
    );

    for (let i = 0; i < nodeMaterials.length; i++) {
      const u = nodeMaterials[i].uniforms;
      u.uTime.value = t;
      u.uOpacity.value = o;
      u.uFocus.value = damp(u.uFocus.value as number, active === i ? 1 : 0, 8, d);
    }
  });

  return (
    <group ref={group} renderOrder={3}>
      {/* 612 line vertices — cheap enough to keep on every tier. */}
      <lineSegments geometry={linkGeometry} material={linkMaterial} renderOrder={3} />

      {NODE_POSITIONS.map((p, i) => (
        <mesh key={TECHNOLOGIES[i].id} position={p} material={nodeMaterials[i]} renderOrder={4}>
          <octahedronGeometry args={[0.155, 0]} />
        </mesh>
      ))}
    </group>
  );
}
