"use client";

import { useEffect, useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import {
  BufferAttribute,
  DoubleSide,
  IcosahedronGeometry,
  Mesh,
  ShaderMaterial,
} from "three";
import { evolveVertex, evolveFragment } from "@/shaders/evolve";
import { journey } from "@/lib/journey";
import { C, C_LIGHT } from "@/lib/palette";
import { themeAt } from "@/lib/theme";
import { clamp, damp, smootherstep } from "@/lib/math";

/**
 * The process object. Scrolling Discover → Scale walks `uEvolve` from 0 to 1,
 * taking one mesh from a turbulent wireframe sphere to a resolved, solid
 * product form. The particle field simultaneously holds the six-knot chain
 * beneath it, so the timeline and the artefact are the same shot.
 */
export function EvolveSystem() {
  const mesh = useRef<Mesh>(null);

  const geometry = useMemo(() => {
    // PolyhedronGeometry is already non-indexed, so every run of three
    // vertices is one triangle — exactly what barycentric wireframing needs.
    // Detail 2 (320 faces). Any denser and the barycentric wireframe stops
    // reading as a structure and turns into a solid mesh of edges.
    const g = new IcosahedronGeometry(1, 2);
    const count = g.attributes.position.count;
    const bary = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      const corner = i % 3;
      bary[i * 3 + corner] = 1;
    }
    g.setAttribute("aBary", new BufferAttribute(bary, 3));
    return g;
  }, []);

  const material = useMemo(
    () =>
      new ShaderMaterial({
        vertexShader: evolveVertex,
        fragmentShader: evolveFragment,
        transparent: true,
        depthWrite: false,
        side: DoubleSide,
        uniforms: {
          uTime: { value: 0 },
          uEvolve: { value: 0 },
          uChaos: { value: 1 },
          uBuild: { value: 0 },
          uOpacity: { value: 0 },
          uLight: { value: 0 },
          uPaper: { value: C_LIGHT.paper.clone() },
          uInk: { value: C_LIGHT.ink.clone() },
          uColorDeep: { value: C.ionDeep.clone() },
          uColorMid: { value: C.ion.clone() },
          uColorHot: { value: C.ember.clone() },
        },
      }),
    [],
  );

  useEffect(
    () => () => {
      geometry.dispose();
      material.dispose();
    },
    [geometry, material],
  );

  const opacity = useRef(0);

  useFrame((state, dt) => {
    const d = Math.min(dt, 1 / 30);
    const t = state.clock.elapsedTime;
    const stage = journey.stage;
    const u = material.uniforms;

    // Held back until the work portal has cleared — a wireframe at low opacity
    // still draws every edge, so it reads as present long before it should.
    const target =
      smootherstep(4.98, 5.32, stage) * (1 - smootherstep(5.82, 6.25, stage));
    opacity.current = damp(opacity.current, target, 4.5, d);
    u.uOpacity.value = opacity.current;

    const m = mesh.current;
    if (m) {
      m.visible = opacity.current > 0.006;
      if (!m.visible) return;
    }

    const evolve = clamp(stage - 5);
    u.uLight.value = themeAt(stage);
    u.uTime.value = t;
    u.uEvolve.value = damp(u.uEvolve.value as number, evolve, 8, d);
    // One construction sweep per process step.
    u.uBuild.value = (evolve * 6) % 1;

    if (m) {
      // Spins fast and loose early, settles as the product resolves.
      m.rotation.y += d * (0.55 - evolve * 0.44);
      m.rotation.x = damp(m.rotation.x, -0.18 + evolve * 0.12, 2, d);
      m.scale.setScalar(0.82 + evolve * 0.16);
    }
  });

  return (
    <mesh
      ref={mesh}
      geometry={geometry}
      material={material}
      position={[0, 1.45, 0.4]}
      renderOrder={3}
    />
  );
}
