"use client";

import { useEffect, useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { AdditiveBlending, NormalBlending, Group, ShaderMaterial } from "three";
import { ringVertex, ringFragment } from "@/shaders/evolve";
import { PILLARS } from "@/data/company";
import { journey } from "@/lib/journey";
import { useAppStore } from "@/store/useAppStore";
import { C, C_LIGHT } from "@/lib/palette";
import { themeAt } from "@/lib/theme";
import { clamp, damp, smootherstep } from "@/lib/math";

/**
 * Four interlocking orbits for the studio section — engineering, design,
 * strategy, innovation sharing one centre. They sit exactly on the great
 * circles the particle field forms in the same beat, so the rings read as the
 * structure the particles are tracing.
 */
export function PillarRings() {
  const group = useRef<Group>(null);

  const rings = useMemo(
    () =>
      PILLARS.map((_, i) => ({
        tilt: (i / 4) * Math.PI,
        yaw: (i / 4) * Math.PI * 1.35 + 0.4,
        speed: 0.05 + i * 0.018 * (i % 2 === 0 ? 1 : -1),
        seed: i * 0.27,
      })),
    [],
  );

  const materials = useMemo(
    () =>
      rings.map(
        (r) =>
          new ShaderMaterial({
            vertexShader: ringVertex,
            fragmentShader: ringFragment,
            transparent: true,
            depthWrite: false,
            blending: AdditiveBlending,
            uniforms: {
              uTime: { value: 0 },
              uWarp: { value: 0.006 },
              uOpacity: { value: 0 },
              uSpeed: { value: r.speed },
              uSeed: { value: r.seed },
              uLight: { value: 0 },
              uPaper: { value: C_LIGHT.paper.clone() },
              uInk: { value: C_LIGHT.ion.clone() },
              uColor: { value: C.ion.clone() },
              uHotColor: { value: C.ionSoft.clone() },
            },
          }),
      ),
    [rings],
  );

  useEffect(() => () => materials.forEach((m) => m.dispose()), [materials]);

  const opacity = useRef(0);

  useFrame((state, dt) => {
    const d = Math.min(dt, 1 / 30);
    const t = state.clock.elapsedTime;
    const stage = journey.stage;

    const target =
      smootherstep(5.55, 6.1, stage) * (1 - smootherstep(6.7, 7.05, stage));
    opacity.current = damp(opacity.current, target, 4.5, d);

    const g = group.current;
    if (g) {
      g.visible = opacity.current > 0.006;
      if (!g.visible) return;
      g.rotation.y = t * 0.03 + journey.smoothPointer.x * 0.16;
      g.rotation.x = journey.smoothPointer.y * -0.1;
    }

    // Additive strokes vanish on paper, so the rings draw rather than glow.
    const theme = themeAt(stage);
    const wantsNormal = theme > 0.5;

    // Hover wins; otherwise the rings light in sequence as the section scrolls.
    const hovered = useAppStore.getState().activePillar;
    const auto = Math.min(3, Math.floor(clamp(stage - 6) * 4.2));
    const focus = hovered >= 0 ? hovered : auto;

    for (let i = 0; i < materials.length; i++) {
      const m = materials[i];
      if (wantsNormal !== (m.blending === NormalBlending)) {
        m.blending = wantsNormal ? NormalBlending : AdditiveBlending;
      }
      const u = m.uniforms;
      u.uTime.value = t;
      u.uLight.value = theme;
      u.uOpacity.value = damp(
        u.uOpacity.value as number,
        opacity.current * (focus === i ? 1 : 0.28),
        5,
        d,
      );
    }
  });

  return (
    <group ref={group} renderOrder={3}>
      {rings.map((r, i) => (
        <mesh
          key={PILLARS[i].id}
          material={materials[i]}
          rotation={[r.tilt, r.yaw, 0, "YXZ"]}
          renderOrder={3}
        >
          <torusGeometry args={[2.42, 0.01, 8, 260]} />
        </mesh>
      ))}
    </group>
  );
}
