"use client";

import { useEffect, useMemo, useRef } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import {
  AdditiveBlending,
  NormalBlending,
  BufferAttribute,
  BufferGeometry,
  ShaderMaterial,
  Sphere,
  Vector2,
  Vector3,
} from "three";
import { buildField } from "@/lib/formations";
import { fieldVertex, fieldFragment } from "@/shaders/field";
import { journey, stageOf } from "@/lib/journey";
import { interaction } from "@/lib/interaction";
import { morphAt } from "@/lib/cameraPath";
import { useAppStore } from "@/store/useAppStore";
import { C, C_LIGHT } from "@/lib/palette";
import { swapAt, themeAt } from "@/lib/theme";
import { clamp, damp, lerp } from "@/lib/math";

/**
 * The morphing particle field. One draw call carries every section of the page.
 */
export function Field() {
  const count = useAppStore((s) => s.quality.particles);
  const size = useThree((s) => s.size);
  const dpr = useThree((s) => s.viewport.dpr);

  // Allocate once at the tier we booted with. Later downgrades shrink the draw
  // range rather than regenerating and re-uploading the attributes, which would
  // stall for tens of milliseconds mid-scroll.
  const capacity = useRef(count).current;
  const data = useMemo(() => buildField(capacity), [capacity]);

  const geometry = useMemo(() => {
    const g = new BufferGeometry();
    g.setAttribute("position", new BufferAttribute(data.base, 3));
    data.targets.forEach((arr, i) => {
      g.setAttribute(`aF${i + 1}`, new BufferAttribute(arr, 3));
    });
    g.setAttribute("aSeed", new BufferAttribute(data.seed, 4));
    // The shader moves points far outside the authored bounds; give the
    // renderer a bounding sphere generous enough that it never culls us.
    g.boundingSphere = new Sphere(new Vector3(0, 0, -8), 42);
    return g;
  }, [data]);

  const material = useMemo(
    () =>
      new ShaderMaterial({
        vertexShader: fieldVertex,
        fragmentShader: fieldFragment,
        transparent: true,
        depthWrite: false,
        depthTest: true,
        blending: AdditiveBlending,
        uniforms: {
          uTime: { value: 0 },
          uMorph: { value: 0 },
          uTurbulence: { value: 0 },
          uSize: { value: 26 },
          uPixelRatio: { value: 1 },
          uIntro: { value: 0 },
          uActiveCluster: { value: -1 },
          uActiveTech: { value: -1 },
          uClusterDim: { value: 0.22 },
          uFocusRange: { value: 26 },
          uPointer: { value: new Vector2() },
          uDrift: { value: 1 },
          uOpacity: { value: 1 },
          uLight: { value: 0 },
          uColorDeep: { value: C.ionDeep.clone() },
          uColorMid: { value: C.ion.clone() },
          uColorHot: { value: C.ionSoft.clone() },
          uInkDeep: { value: C_LIGHT.dustDeep.clone() },
          uInkMid: { value: C_LIGHT.dustMid.clone() },
          uInkHot: { value: C_LIGHT.dustHot.clone() },
        },
      }),
    [],
  );

  useEffect(() => () => geometry.dispose(), [geometry]);
  useEffect(() => () => material.dispose(), [material]);

  useEffect(() => {
    geometry.setDrawRange(0, Math.min(count, capacity));
  }, [count, capacity, geometry]);

  useEffect(() => {
    material.uniforms.uPixelRatio.value = dpr;
    // Point size is authored against a 900px-tall frame.
    material.uniforms.uSize.value = 24 * (size.height / 900);
  }, [dpr, size.height, material]);

  const prevMorph = useRef(0);
  const turbulence = useRef(0);
  const cluster = useRef(-1);
  const tech = useRef(-1);

  useFrame((state, dt) => {
    const d = Math.min(dt, 1 / 30);
    const u = material.uniforms;
    const stage = journey.stage;

    u.uTime.value = state.clock.elapsedTime;

    const morph = morphAt(stage);
    const rate = Math.abs(morph - prevMorph.current) / Math.max(d, 1e-4);
    prevMorph.current = morph;

    // The field visibly energises while it reconfigures, and settles once the
    // new formation has landed.
    const target = clamp(rate * 0.19 + Math.abs(journey.velocity) * 0.0006, 0, 1);
    turbulence.current = damp(turbulence.current, target, 5.5, d);
    interaction.energy = turbulence.current;

    u.uMorph.value = morph;
    u.uTurbulence.value = turbulence.current;
    u.uIntro.value = journey.intro;
    (u.uPointer.value as Vector2).set(
      journey.smoothPointer.x,
      journey.smoothPointer.y,
    );

    // Read the store transiently — highlighting must not re-render the tree.
    const s = useAppStore.getState();
    const nearServices = 1 - clamp(Math.abs(stage - 2));
    const nearTech = 1 - clamp(Math.abs(stage - 3));
    cluster.current = nearServices > 0.05 ? s.activeService : -1;
    tech.current = nearTech > 0.05 ? s.activeTech : -1;
    u.uActiveCluster.value = cluster.current;
    u.uActiveTech.value = tech.current;

    // Environment. Additive light does nothing on paper, so the material flips
    // to normal blending as the field crosses over. The switch happens at the
    // exact midpoint, where the field has also dipped out — so the change of
    // blend mode is never visible.
    const theme = themeAt(stage);
    const swap = swapAt(theme);
    u.uLight.value = theme;

    const wantsNormal = theme > 0.5;
    if (wantsNormal !== (material.blending === NormalBlending)) {
      material.blending = wantsNormal ? NormalBlending : AdditiveBlending;
    }

    // The field steps back to a supporting role wherever the DOM carries the
    // weight: through every copy-dense beat on portrait, and in the studio
    // section — which has no sticky frame — on all viewports.
    const portrait = size.width < size.height;
    const copyHeavy = stage > 1.5 && stage < 6.05;
    // Studio, insights and clients all carry dense content over the field,
    // right up to the CTA.
    const studio = stage >= 5.9 && stage < stageOf("cta");
    // Ink covers more ground than glow at the same alpha, so the light acts
    // need to be held back further than the dark ones.
    const studioDim = lerp(0.55, 0.38, theme);
    const dim = portrait && copyHeavy ? 0.46 : studio ? studioDim : 1;
    u.uOpacity.value = damp(
      u.uOpacity.value as number,
      lerp(dim, 0.3, swap),
      4.5,
      d,
    );

    // Wider depth range inside the corridor so the far end still reads.
    u.uFocusRange.value = damp(
      u.uFocusRange.value as number,
      stage > 3.4 && stage < 4.9 ? 34 : 22,
      2.5,
      d,
    );
  });

  return (
    <points
      geometry={geometry}
      material={material}
      frustumCulled={false}
      renderOrder={4}
    />
  );
}
