"use client";

import { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import {
  Bloom,
  ChromaticAberration,
  DepthOfField,
  EffectComposer,
  ToneMapping,
  Vignette,
} from "@react-three/postprocessing";
import {
  BlendFunction,
  ToneMappingMode,
  KernelSize,
  type BloomEffect,
  type ChromaticAberrationEffect,
  type DepthOfFieldEffect,
} from "postprocessing";
import { Vector3 } from "three";
import { useAppStore } from "@/store/useAppStore";
import { journey, stageOf } from "@/lib/journey";
import { interaction } from "@/lib/interaction";
import { themeAt } from "@/lib/theme";
import { clamp, damp, lerp, smootherstep } from "@/lib/math";

/**
 * Post chain. Tone mapping runs here rather than on the renderer so custom
 * shaders and standard materials go through exactly the same curve, and the
 * grade reacts to the scene: bloom lifts at the hero and the closing CTA,
 * aberration spikes while the field reconfigures.
 */
export function Effects() {
  const quality = useAppStore((s) => s.quality);

  const bloom = useRef<BloomEffect>(null);
  const vignette = useRef<{ darkness: number } | null>(null);
  const chroma = useRef<ChromaticAberrationEffect>(null);
  const dof = useRef<DepthOfFieldEffect>(null);

  // Mutated in place each frame; the effect holds it by reference.
  const focusTarget = useMemo(() => new Vector3(0, 0, 0), []);

  useFrame((_, dt) => {
    const d = Math.min(dt, 1 / 30);
    const stage = journey.stage;

    // Focus rides the subject: the core, then the portal deeper in the corridor.
    const inWork =
      smootherstep(3.5, 4.1, stage) * (1 - smootherstep(4.7, 5.1, stage));
    focusTarget.set(0, 0, -3.1 * inWork);

    if (dof.current && dof.current.target !== focusTarget) {
      dof.current.target = focusTarget;
    }

    const climax = Math.max(
      1 - clamp(Math.abs(stage - 0) / 1.3),
      1 - clamp(Math.abs(stage - stageOf("cta")) / 1.1),
    );

    // Bloom, aberration and a heavy vignette are all dark-environment devices.
    // On paper they read as haze and dirt, so the grade opens right up.
    const theme = themeAt(stage);

    if (bloom.current) {
      const dark = (0.34 + climax * 0.2 + interaction.energy * 0.35) * journey.intro;
      bloom.current.intensity = damp(
        bloom.current.intensity,
        lerp(dark, 0.16 * journey.intro, theme),
        3,
        d,
      );

      // On paper almost the whole frame sits above a dark-scene bloom
      // threshold, so bloom stops being a highlight and becomes fog. Raising
      // the threshold keeps it to genuine speculars.
      const lum = bloom.current.luminanceMaterial;
      if (lum) lum.threshold = damp(lum.threshold, lerp(0.32, 0.94, theme), 3, d);
    }

    if (vignette.current) {
      vignette.current.darkness = damp(vignette.current.darkness, lerp(0.82, 0.16, theme), 3, d);
    }

    if (chroma.current) {
      // Radial modulation keeps the centre of frame clean and pushes the
      // fringing to the edges, which is where a real lens puts it.
      chroma.current.radialModulation = true;
      chroma.current.modulationOffset = 0.3;
      const o = (0.00035 + interaction.energy * 0.0038) * lerp(1, 0.35, theme);
      chroma.current.offset.set(o, o * 0.62);
    }
  });

  return (
    <EffectComposer multisampling={0} enableNormalPass={false}>
      {quality.depthOfField ? (
        <DepthOfField
          ref={dof}
          focusDistance={7.2}
          focusRange={5.5}
          bokehScale={2.6}
          resolutionScale={0.5}
        />
      ) : (
        <></>
      )}

      <Bloom
        ref={bloom}
        intensity={0.4}
        luminanceThreshold={0.32}
        luminanceSmoothing={0.35}
        kernelSize={KernelSize.MEDIUM}
        mipmapBlur
        radius={0.72}
      />

      {quality.chromaticAberration ? (
        <ChromaticAberration ref={chroma} offset={[0.0004, 0.00025]} />
      ) : (
        <></>
      )}

      <Vignette
        ref={vignette as never}
        offset={0.24}
        darkness={0.82}
        blendFunction={BlendFunction.NORMAL}
      />

      <ToneMapping mode={ToneMappingMode.AGX} />
    </EffectComposer>
  );
}
