"use client";

import { useRef } from "react";
import { Environment, Lightformer, PerformanceMonitor } from "@react-three/drei";
import { useAppStore } from "@/store/useAppStore";
import { Rig } from "./Rig";
import { Atmosphere } from "./Atmosphere";
import { Field } from "./Field";
import { Dust } from "./Dust";
import { HeroCore } from "./HeroCore";
import { Constellation } from "./Constellation";
import { Portal } from "./Portal";
import { EvolveSystem } from "./EvolveSystem";
import { PillarRings } from "./PillarRings";
import { Effects } from "./Effects";

/**
 * The scene graph. Every section-specific object fades itself in and out
 * against the journey stage rather than mounting and unmounting, so nothing
 * ever compiles a shader mid-scroll.
 */
export function Scene() {
  const quality = useAppStore((s) => s.quality);
  const downgrade = useAppStore((s) => s.downgrade);
  const declined = useRef(false);

  return (
    <>
      <PerformanceMonitor
        // Integrated GPUs sit in the high-30s on a scene like this and look
        // fine; only drop a tier when the frame budget is genuinely blown.
        bounds={() => [34, 58]}
        flipflops={3}
        onFallback={() => {
          if (declined.current) return;
          declined.current = true;
          downgrade();
        }}
      />

      {/* The dome covers the frame; this is only what shows if it ever does not. */}
      <color attach="background" args={["#04050a"]} />

      <Rig />
      <Atmosphere />

      {quality.environment && (
        <Environment resolution={256} frames={1}>
          <Lightformer
            intensity={2.4}
            position={[0, 4, -3]}
            scale={[10, 5, 1]}
            color="#a8c2ff"
          />
          <Lightformer
            intensity={1.1}
            position={[-5, -1, 2]}
            rotation={[0, Math.PI / 2, 0]}
            scale={[8, 4, 1]}
            color="#ff8a5b"
          />
          <Lightformer
            intensity={0.7}
            position={[5, 1, 1]}
            rotation={[0, -Math.PI / 2, 0]}
            scale={[6, 6, 1]}
            color="#2b47c9"
          />
          <Lightformer
            form="ring"
            intensity={1.6}
            position={[0, 0, 6]}
            scale={4}
            color="#6e9bff"
          />
        </Environment>
      )}

      <ambientLight intensity={0.18} color="#8fa8ff" />
      <directionalLight position={[3, 5, 4]} intensity={0.5} color="#cddaff" />

      <HeroCore />
      <Field />
      <Constellation />
      <Portal />
      <EvolveSystem />
      <PillarRings />
      <Dust />

      <Effects />
    </>
  );
}
