"use client";

import { useEffect, useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import {
  AdditiveBlending,
  NormalBlending,
  DoubleSide,
  Group,
  Mesh,
  ShaderMaterial,
} from "three";
import { coreVertex, coreFragment, shellVertex, shellFragment } from "@/shaders/core";
import { ringVertex, ringFragment } from "@/shaders/evolve";
import { journey } from "@/lib/journey";
import { useAppStore } from "@/store/useAppStore";
import { C, C_LIGHT } from "@/lib/palette";
import { themeAt } from "@/lib/theme";
import { clamp, damp, lerp, smootherstep } from "@/lib/math";

const RINGS = [
  { radius: 2.32, tube: 0.012, rot: [-0.42, 0.2, 0.15], speed: 0.075, seed: 0.0 },
  { radius: 2.76, tube: 0.009, rot: [0.28, -0.85, -0.3], speed: -0.055, seed: 0.37 },
  { radius: 3.2, tube: 0.007, rot: [1.15, 0.5, 0.6], speed: 0.04, seed: 0.71 },
];

/** Small reflective chips orbiting the core — the only truly metallic surfaces
 *  in the scene, there to pick up the procedural environment. */
const SHARDS = [
  { r: 2.0, phase: 0.0, y: 0.55, scale: 0.09, speed: 0.14 },
  { r: 2.45, phase: 2.1, y: -0.72, scale: 0.065, speed: -0.11 },
  { r: 1.72, phase: 4.0, y: 1.05, scale: 0.055, speed: 0.19 },
  { r: 2.9, phase: 5.3, y: 0.12, scale: 0.075, speed: -0.08 },
  { r: 2.2, phase: 1.1, y: -1.15, scale: 0.05, speed: 0.16 },
];

export function HeroCore() {
  const detail = useAppStore((s) => s.quality.coreDetail);
  const showShards = useAppStore((s) => s.quality.shards);

  const group = useRef<Group>(null);
  const coreMesh = useRef<Mesh>(null);
  const shellMesh = useRef<Mesh>(null);
  const shards = useRef<(Mesh | null)[]>([]);

  const coreMaterial = useMemo(
    () =>
      new ShaderMaterial({
        vertexShader: coreVertex,
        fragmentShader: coreFragment,
        transparent: true,
        depthWrite: true,
        uniforms: {
          uTime: { value: 0 },
          uAmp: { value: 0.28 },
          uIntro: { value: 0 },
          uPulse: { value: 0 },
          uOpacity: { value: 1 },
          uLight: { value: 0 },
          uInkDeep: { value: C_LIGHT.sculptDeep.clone() },
          uInkLite: { value: C_LIGHT.sculptLite.clone() },
          uPaper: { value: C_LIGHT.paper.clone() },
          uColorDeep: { value: C.ionDeep.clone() },
          uColorMid: { value: C.ion.clone() },
          uColorHot: { value: C.ember.clone() },
        },
      }),
    [],
  );

  const shellMaterial = useMemo(
    () =>
      new ShaderMaterial({
        vertexShader: shellVertex,
        fragmentShader: shellFragment,
        transparent: true,
        depthWrite: false,
        side: DoubleSide,
        blending: AdditiveBlending,
        uniforms: {
          uColor: { value: C.ionSoft.clone() },
          uOpacity: { value: 0.5 },
          uLight: { value: 0 },
          uInk: { value: C_LIGHT.sculptDeep.clone() },
          uPaper: { value: C_LIGHT.paper.clone() },
        },
      }),
    [],
  );

  const ringMaterials = useMemo(
    () =>
      RINGS.map(
        (r) =>
          new ShaderMaterial({
            vertexShader: ringVertex,
            fragmentShader: ringFragment,
            transparent: true,
            depthWrite: false,
            blending: AdditiveBlending,
            uniforms: {
              uTime: { value: 0 },
              uWarp: { value: 0.01 },
              uOpacity: { value: 1 },
              uSpeed: { value: r.speed },
              uSeed: { value: r.seed },
              uLight: { value: 0 },
              uPaper: { value: C_LIGHT.paper.clone() },
              uInk: { value: C_LIGHT.ion.clone() },
              uColor: { value: C.ion.clone() },
              uHotColor: { value: C.ionSoft.clone() },
            },
          }),
      ),
    [],
  );

  useEffect(
    () => () => {
      coreMaterial.dispose();
      shellMaterial.dispose();
      ringMaterials.forEach((m) => m.dispose());
    },
    [coreMaterial, shellMaterial, ringMaterials],
  );

  const opacity = useRef(0);

  useFrame((state, dt) => {
    const d = Math.min(dt, 1 / 30);
    const t = state.clock.elapsedTime;
    const stage = journey.stage;

    // The core belongs to the hero; it dissolves as the field takes over.
    const target = (1 - smootherstep(0.45, 1.5, stage)) * journey.intro;
    opacity.current = damp(opacity.current, target, 5, d);
    const o = opacity.current;

    const g = group.current;
    if (g) {
      g.visible = o > 0.008;
      if (!g.visible) return;

      g.rotation.y = t * 0.055 + journey.smoothPointer.x * 0.22;
      g.rotation.x = Math.sin(t * 0.09) * 0.06 - journey.smoothPointer.y * 0.16;

      // Recedes and shrinks slightly as it hands off to the particle field.
      const s = 1 - smootherstep(0.4, 1.5, stage) * 0.35;
      g.scale.setScalar(s * (0.6 + journey.intro * 0.4));
      g.position.z = -smootherstep(0.4, 1.5, stage) * 2.4;
    }

    // Emissive in the dark, a shaded solid on paper — and the additive shell
    // and rings become drawn edges, since additive light does nothing on white.
    const theme = themeAt(stage);
    const wantsNormal = theme > 0.5;
    if (wantsNormal !== (shellMaterial.blending === NormalBlending)) {
      shellMaterial.blending = wantsNormal ? NormalBlending : AdditiveBlending;
      for (const m of ringMaterials) {
        m.blending = wantsNormal ? NormalBlending : AdditiveBlending;
      }
    }
    coreMaterial.uniforms.uLight.value = theme;
    shellMaterial.uniforms.uLight.value = theme;

    coreMaterial.uniforms.uTime.value = t;
    coreMaterial.uniforms.uIntro.value = journey.intro;
    coreMaterial.uniforms.uOpacity.value = o;
    coreMaterial.uniforms.uPulse.value = damp(
      coreMaterial.uniforms.uPulse.value as number,
      clamp(Math.abs(journey.velocity) * 0.012, 0, 1),
      4,
      d,
    );

    shellMaterial.uniforms.uOpacity.value = o * lerp(0.16, 0.5, theme);

    for (let i = 0; i < ringMaterials.length; i++) {
      ringMaterials[i].uniforms.uTime.value = t;
      ringMaterials[i].uniforms.uLight.value = theme;
      ringMaterials[i].uniforms.uOpacity.value = o;
    }

    if (shellMesh.current) {
      shellMesh.current.rotation.y = -t * 0.09;
      shellMesh.current.rotation.z = t * 0.04;
    }

    for (let i = 0; i < SHARDS.length; i++) {
      const m = shards.current[i];
      if (!m) continue;
      const s = SHARDS[i];
      const a = s.phase + t * s.speed;
      m.position.set(Math.cos(a) * s.r, s.y + Math.sin(t * 0.3 + s.phase) * 0.12, Math.sin(a) * s.r);
      m.rotation.x = t * 0.4 + s.phase;
      m.rotation.y = t * 0.3;
      m.scale.setScalar(s.scale * o);
    }
  });

  return (
    <group ref={group} renderOrder={1}>
      <mesh ref={coreMesh} material={coreMaterial} renderOrder={1}>
        <icosahedronGeometry args={[0.86, detail]} />
      </mesh>

      <mesh ref={shellMesh} material={shellMaterial} renderOrder={2}>
        <icosahedronGeometry args={[1.44, 1]} />
      </mesh>

      {RINGS.map((r, i) => (
        <mesh
          key={i}
          material={ringMaterials[i]}
          rotation={r.rot as [number, number, number]}
          renderOrder={3}
        >
          <torusGeometry args={[r.radius, r.tube, 8, 220]} />
        </mesh>
      ))}

      {showShards &&
        SHARDS.map((s, i) => (
          <mesh
            key={i}
            ref={(el) => {
              shards.current[i] = el;
            }}
            renderOrder={1}
          >
            <octahedronGeometry args={[1, 0]} />
            <meshPhysicalMaterial
              color="#0d1220"
              metalness={1}
              roughness={0.14}
              envMapIntensity={2.4}
              clearcoat={1}
              clearcoatRoughness={0.15}
            />
          </mesh>
        ))}
    </group>
  );
}
