import { simplex3d, fbm3d, helpers } from "./chunks/noise";

/**
 * The hero centrepiece: a displaced sphere that reads as a living computational
 * core rather than a spinning ball. Normals are rebuilt from the displaced
 * surface so the lighting stays honest, and the noise field doubles as an
 * emissive "vein" map.
 */

export const coreVertex = /* glsl */ `
uniform float uTime;
uniform float uAmp;
uniform float uIntro;
uniform float uPulse;

varying vec3 vNormalW;
varying vec3 vViewDir;
varying vec3 vLocal;
varying float vDisp;

${simplex3d}
${fbm3d}
${helpers}

float displace(vec3 dir) {
  float t = uTime * 0.14;
  float n = fbm(dir * 1.45 + vec3(0.0, t * 0.9, t * 0.55), 3, 2.05, 0.52);
  float ridge = 1.0 - abs(snoise(dir * 2.35 + vec3(t * 0.7)));
  return n * 0.55 + pow(ridge, 3.0) * 0.3;
}

void main() {
  vec3 dir = normalize(position);
  float amp = uAmp * mix(0.25, 1.0, uIntro) * (1.0 + uPulse * 0.55);

  float d = displace(dir);
  vDisp = d;

  vec3 p = dir * (1.0 + d * amp);

  // Rebuild the normal from two tangential samples of the same field.
  vec3 tangent = orthogonal(dir);
  vec3 bitangent = normalize(cross(dir, tangent));
  const float eps = 0.045;
  vec3 da = normalize(dir + tangent * eps);
  vec3 db = normalize(dir + bitangent * eps);
  vec3 pa = da * (1.0 + displace(da) * amp);
  vec3 pb = db * (1.0 + displace(db) * amp);
  vec3 n = normalize(cross(pa - p, pb - p));
  if (dot(n, dir) < 0.0) n = -n;

  vLocal = p;
  vNormalW = normalize(mat3(modelMatrix) * n);

  vec4 world = modelMatrix * vec4(p, 1.0);
  vViewDir = normalize(cameraPosition - world.xyz);

  gl_Position = projectionMatrix * viewMatrix * world;
}
`;

export const coreFragment = /* glsl */ `
precision highp float;

uniform vec3 uColorDeep;
uniform vec3 uColorMid;
uniform vec3 uColorHot;
uniform float uTime;
uniform float uOpacity;
uniform float uPulse;
uniform float uLight;
uniform vec3 uInkDeep;
uniform vec3 uInkLite;
uniform vec3 uPaper;

varying vec3 vNormalW;
varying vec3 vViewDir;
varying vec3 vLocal;
varying float vDisp;

void main() {
  vec3 N = normalize(vNormalW);
  vec3 V = normalize(vViewDir);

  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 2.7);

  // Two key lights, cool from above, warm rake from below-left.
  float key = clamp(dot(N, normalize(vec3(0.35, 0.78, 0.52))), 0.0, 1.0);
  float rake = clamp(dot(N, normalize(vec3(-0.72, -0.28, 0.42))), 0.0, 1.0);

  // Deliberately dark: the core is a dense object catching light, not a lamp.
  // Everything here is tuned to survive bloom without blowing out the headline
  // that sits in front of it.
  vec3 col = uColorDeep * 0.05;
  col += uColorMid * pow(key, 2.1) * 0.15;
  col += uColorHot * pow(rake, 3.0) * 0.09;

  // Emissive ridges: the surface looks powered, not painted.
  float ridge = smoothstep(0.55, 0.98, vDisp);
  col += mix(uColorMid, uColorHot, ridge) * ridge * (0.3 + uPulse * 0.4);

  // Rim only — the silhouette carries the read.
  col += uColorMid * fres * 0.5;
  col += vec3(1.0) * pow(fres, 7.0) * 0.2;

  // Slow vertical scan, a single band travelling the body.
  float band = exp(-pow((vLocal.y - sin(uTime * 0.24) * 1.15) * 5.5, 2.0));
  col += uColorHot * band * 0.12;

  /* ---------------------------------------------------------------
     Light environment.

     An inverted glow reads as a stain on paper. What works instead is
     an honestly shaded solid: lambert body, a real specular hit, and
     bounce light off the page keeping the shadow side alive. The noise
     ridges stop being emissive veins and become creases in the surface.
  --------------------------------------------------------------- */
  vec3 L = normalize(vec3(0.42, 0.86, 0.52));
  float lam = clamp(dot(N, L), 0.0, 1.0);
  vec3 H = normalize(L + V);
  float spec = pow(clamp(dot(N, H), 0.0, 1.0), 46.0);

  vec3 solid = mix(uInkDeep, uInkLite, pow(lam, 0.7));
  solid *= 1.0 - ridge * 0.3;

  // Bounce off the page.
  float bounce = clamp(dot(N, vec3(0.0, -1.0, 0.2)), 0.0, 1.0);
  solid += uPaper * bounce * 0.18;

  solid += vec3(1.0) * spec * 0.6;
  // The rim picks up the environment rather than emitting.
  solid = mix(solid, uPaper, pow(fres, 3.2) * 0.34);

  gl_FragColor = vec4(mix(col, solid, uLight), uOpacity);
}
`;

/**
 * Thin faceted shell that sits just outside the core. Uses the scene's
 * procedural environment map for reflections, so the core has something to
 * catch light on.
 */
export const shellVertex = /* glsl */ `
varying vec3 vNormalW;
varying vec3 vViewDir;

void main() {
  vNormalW = normalize(mat3(modelMatrix) * normal);
  vec4 world = modelMatrix * vec4(position, 1.0);
  vViewDir = normalize(cameraPosition - world.xyz);
  gl_Position = projectionMatrix * viewMatrix * world;
}
`;

export const shellFragment = /* glsl */ `
precision highp float;

uniform vec3 uColor;
uniform float uOpacity;
uniform float uLight;
uniform vec3 uInk;
uniform vec3 uPaper;

varying vec3 vNormalW;
varying vec3 vViewDir;

void main() {
  vec3 N = normalize(vNormalW);
  vec3 V = normalize(vViewDir);
  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.2);

  vec3 glow = uColor * (0.4 + fres * 1.6);
  vec3 ink = mix(uPaper, uInk, clamp(fres * 1.5, 0.0, 1.0));

  float alpha = fres * uOpacity * mix(1.0, 1.7, uLight);
  if (alpha < 0.002) discard;
  gl_FragColor = vec4(mix(glow, ink, uLight), alpha);
}
`;
