"use client";

import { useEffect, useMemo, useRef } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Points,
  ShaderMaterial,
  Sphere,
  Vector2,
  Vector3,
} from "three";
import { dustVertex, dustFragment } from "@/shaders/dust";
import { journey } from "@/lib/journey";
import { useAppStore } from "@/store/useAppStore";
import { makeRng } from "@/lib/math";
import { themeAt } from "@/lib/theme";
import { C } from "@/lib/palette";

const BOX = { w: 26, h: 16, d: 34 };

/**
 * Foreground motes locked to the camera. Cheap, and they do more for the sense
 * of depth than any amount of extra geometry in the middle distance.
 */
export function Dust() {
  const count = useAppStore((s) => s.quality.dust);
  const dpr = useThree((s) => s.viewport.dpr);
  const ref = useRef<Points>(null);

  const geometry = useMemo(() => {
    const rng = makeRng(0xd0571);
    const pos = new Float32Array(count * 3);
    const seed = new Float32Array(count * 3);

    for (let i = 0; i < count; i++) {
      pos[i * 3] = (rng() - 0.5) * BOX.w;
      pos[i * 3 + 1] = (rng() - 0.5) * BOX.h;
      pos[i * 3 + 2] = rng() * BOX.d;

      seed[i * 3] = 0.2 + Math.pow(rng(), 2.2) * 1.4; // size
      seed[i * 3 + 1] = rng(); // speed
      seed[i * 3 + 2] = rng(); // phase
    }

    const g = new BufferGeometry();
    g.setAttribute("position", new BufferAttribute(pos, 3));
    g.setAttribute("aSeed", new BufferAttribute(seed, 3));
    g.boundingSphere = new Sphere(new Vector3(0, 0, -BOX.d / 2), BOX.d);
    return g;
  }, [count]);

  const material = useMemo(
    () =>
      new ShaderMaterial({
        vertexShader: dustVertex,
        fragmentShader: dustFragment,
        transparent: true,
        depthWrite: false,
        blending: AdditiveBlending,
        uniforms: {
          uTime: { value: 0 },
          uSize: { value: 14 },
          uPixelRatio: { value: 1 },
          uBoxDepth: { value: BOX.d },
          uPointer: { value: new Vector2() },
          uOpacity: { value: 0 },
          uColorA: { value: C.ionSoft.clone() },
          uColorB: { value: C.ion.clone() },
        },
      }),
    [],
  );

  useEffect(() => () => geometry.dispose(), [geometry]);
  useEffect(() => () => material.dispose(), [material]);
  useEffect(() => {
    material.uniforms.uPixelRatio.value = dpr;
  }, [dpr, material]);

  useFrame((state) => {
    material.uniforms.uTime.value = state.clock.elapsedTime;
    // Motes are glow. On paper there is nothing for them to glow against, and
    // the light acts are deliberately cleaner, so they fade right out.
    material.uniforms.uOpacity.value =
      journey.intro * 0.55 * (1 - themeAt(journey.stage));
    (material.uniforms.uPointer.value as Vector2).set(
      journey.smoothPointer.x,
      journey.smoothPointer.y,
    );

    // Lock to the camera so the motes always frame the shot.
    const p = ref.current;
    if (p) {
      p.position.copy(state.camera.position);
      p.quaternion.copy(state.camera.quaternion);
    }
  });

  return (
    <points
      ref={ref}
      geometry={geometry}
      material={material}
      frustumCulled={false}
      renderOrder={6}
    />
  );
}
